import{_ as o,c as a,o as t,ag as r}from"./chunks/framework.DZ_cNctr.js";const u=JSON.parse('{"title":"Remote URLs","description":"Stream OME-Zarr data from S3, Cloudflare R2, GCS, Azure Blob or your own server, as a folder or as one zipped .ozx or .zip file, Dropbox file links included. Only the chunks you look at are fetched, so nothing needs downloading first.","frontmatter":{"title":"Remote URLs","description":"Stream OME-Zarr data from S3, Cloudflare R2, GCS, Azure Blob or your own server, as a folder or as one zipped .ozx or .zip file, Dropbox file links included. Only the chunks you look at are fetched, so nothing needs downloading first."},"headers":[],"relativePath":"guides/remote-urls.md","filePath":"guides/remote-urls.md"}'),s={name:"guides/remote-urls.md"};function i(n,e,l,d,p,h){return t(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="remote-urls" tabindex="-1">Remote URLs <a class="header-anchor" href="#remote-urls" aria-label="Permalink to &quot;Remote URLs&quot;">​</a></h1><p>Stream OME-ZARR data directly from remote servers without downloading anything.</p><p>Streaming turns every chunk into an HTTP range request, so what you serve from matters more than how fast your connection is. <a href="https://www.find-nuclei.com/blog/local-vs-remote-ome-zarr" target="_blank" rel="noreferrer">Your OME-ZARR Storage Setup Is Slowing You Down</a> covers which storage handles that pattern well, and why an NFS or SMB mount usually does not.</p><h2 id="opening-a-remote-dataset" tabindex="-1">Opening a Remote Dataset <a class="header-anchor" href="#opening-a-remote-dataset" aria-label="Permalink to &quot;Opening a Remote Dataset&quot;">​</a></h2><ol><li>Click <strong>Open Image</strong> on the landing page</li><li>Paste an OME-ZARR URL into the URL field</li><li>Click <strong>Load from URL</strong></li></ol><p>The viewer streams tiles on demand. Only the data you&#39;re currently viewing is fetched.</p><p>The address can point at a Zarr folder or at a dataset zipped into one <code>.ozx</code> or <code>.zip</code> file. See <a href="#zipped-datasets">Zipped Datasets</a>. A Zeiss CZI file opens from its address too. See <a href="./zeiss-czi.html">Zeiss CZI Files</a>.</p><h2 id="public-data-sources" tabindex="-1">Public Data Sources <a class="header-anchor" href="#public-data-sources" aria-label="Permalink to &quot;Public Data Sources&quot;">​</a></h2><p>The <a href="https://idr.openmicroscopy.org" target="_blank" rel="noreferrer">Image Data Resource (IDR)</a> hosts thousands of public microscopy datasets in OME-ZARR format. Browse the IDR, find a dataset, and copy its ZARR URL to open it in Find Nuclei Viewer.</p><p>Example URLs:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://uk1s3.embassy.ebi.ac.uk/idr/zarr/v0.4/idr0079A/idr0079_images.zarr</span></span>
<span class="line"><span>https://uk1s3.embassy.ebi.ac.uk/idr/zarr/v0.4/idr0001A/2551.zarr</span></span></code></pre></div><h2 id="cors-requirements" tabindex="-1">CORS Requirements <a class="header-anchor" href="#cors-requirements" aria-label="Permalink to &quot;CORS Requirements&quot;">​</a></h2><p>Remote servers must have <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS" target="_blank" rel="noreferrer">CORS</a> enabled for the viewer to access data. Most public OME-ZARR servers (IDR, BioImage Archive) already support CORS.</p><h2 id="zipped-datasets" tabindex="-1">Zipped Datasets <a class="header-anchor" href="#zipped-datasets" aria-label="Permalink to &quot;Zipped Datasets&quot;">​</a></h2><p>A dataset zipped into one <code>.ozx</code> or <code>.zip</code> file opens from its address too. Paste the address and click <strong>Load from URL</strong>. It opens in 2D and in 3D, like a folder.</p><p>The viewer reads the file&#39;s table of contents from its end, then only the parts it needs for the view. It does not download the whole file.</p><p>The server needs two things:</p><ul><li><strong>CORS</strong>, as for any address.</li><li><strong>Range requests</strong>, so it can send part of a file. S3, Cloudflare R2, Google Cloud Storage and most web servers do. If a server sends the whole file instead, the viewer stops and says so. Download the file and open it from your disk.</li></ul><p>An address with a query, such as a presigned S3 link to the file, works as it is.</p><p>Zip the dataset without compression for the fastest reads. A compressed entry is read whole the first time it is needed. <a href="./local-files.html#a-dataset-in-a-single-file">A Dataset in a Single File</a> shows how to make the archive.</p><h3 id="dropbox-file-links" tabindex="-1">Dropbox file links <a class="header-anchor" href="#dropbox-file-links" aria-label="Permalink to &quot;Dropbox file links&quot;">​</a></h3><p>Put the <code>.ozx</code> or <code>.zip</code> file in Dropbox, copy its link (<strong>Share</strong>, then <strong>Copy link</strong>), and paste the link as it is. The viewer reads the file from Dropbox&#39;s download address. The address bar and <strong>Copy link</strong> keep the link you pasted.</p><p>Dropbox file links work, but they are not the best way to share data for viewing. Dropbox takes several seconds to answer each read, so opening a large image can take a minute or more. For data you view often, put it in object storage (S3, R2, GCS) or on any web server that supports range requests.</p><p>Dropbox folder links, Google Drive, OneDrive and Proton Drive are not supported. See <a href="#cloud-drives">Cloud Drives</a>.</p><p>Anyone who has the link can open the file, in the viewer or anywhere else.</p><h2 id="cloud-drives" tabindex="-1">Cloud Drives <a class="header-anchor" href="#cloud-drives" aria-label="Permalink to &quot;Cloud Drives&quot;">​</a></h2><p>Dropbox folder links, Google Drive, OneDrive and Proton Drive do not open. They share a web page, not the files inside, and the viewer has to read the files one by one. Proton Drive is also end-to-end encrypted, so its servers cannot hand out readable files at all.</p><p>What works instead:</p><ul><li><strong>Zip it and share the file from Dropbox.</strong> Zip the dataset into one <code>.ozx</code> file and share that file&#39;s Dropbox link. See <a href="#dropbox-file-links">Dropbox file links</a>.</li><li><strong>Open it from your disk.</strong> Download the dataset, then open the folder (Chrome or Edge) or a zipped <code>.ozx</code> or <code>.zip</code> file (any browser). Both work in 2D and in 3D. See <a href="./local-files.html">Local Files</a>.</li><li><strong>Put it on object storage with CORS enabled</strong>, such as S3, Cloudflare R2 or Google Cloud Storage, and open its URL.</li><li><strong>Serve it from your own server.</strong> The <a href="./data-server.html">Data Server guide</a> covers it.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><p>Click <strong>Open Example</strong> on the landing page to browse a curated list of public datasets that are known to work well with Find Nuclei Viewer.</p>`,31)])])}const f=o(s,[["render",i]]);export{u as __pageData,f as default};
